// EXOTIC LILY — BumbleBee rundll32 invocation from mounted ISO/IMG
// Pattern: rundll32.exe "<DriveLetter>:\<file>.dll",<ExportName>
// where DriveLetter is a removable/virtual mount (D-Z, never C:),
// the parent is explorer.exe (LNK double-click) or cmd.exe (batch),
// and the cmd-line uses the rundll32 "DLL,Export" comma syntax.
let LookbackDays = 14d;
let UserLoaders = dynamic(["rundll32.exe","regsvr32.exe","odbcconf.exe"]);
DeviceProcessEvents
| where Timestamp > ago(LookbackDays)
| where AccountName !endswith "$"
| where FileName in~ (UserLoaders)
// rundll32 with a DLL + comma + export — the BumbleBee invocation shape
| where ProcessCommandLine matches regex @"(?i)[D-Z]:\\[^ ,\"]+\.dll[\"]?\s*,\s*[A-Za-z_][A-Za-z0-9_]{2,40}"
// Exclude Windows-shipped DLLs and signed installers running from C:
| where ProcessCommandLine !contains @"C:\Windows\"
| where ProcessCommandLine !contains @"C:\Program Files"
// Parent is typically explorer (LNK click), cmd, or wscript — NOT msiexec / setup
| where InitiatingProcessFileName in~ ("explorer.exe","cmd.exe","wscript.exe","cscript.exe","powershell.exe","outlook.exe")
| extend MountDrive = extract(@"(?i)([D-Z]):\\", 1, ProcessCommandLine),
         DllPath    = extract(@"(?i)([D-Z]:\\[^ ,\"]+\.dll)", 1, ProcessCommandLine),
         Export     = extract(@"(?i)\.dll[\"]?\s*,\s*([A-Za-z_][A-Za-z0-9_]{2,40})", 1, ProcessCommandLine)
| where isnotempty(MountDrive) and isnotempty(Export)
// Final FP suppression: DLL must NOT be a known signed Windows component
| where Export !in~ ("PrintUIEntry","OpenAs_RunDLL","Control_RunDLL","ShellExec_RunDLL","InstallHinfSection")
| project Timestamp, DeviceName, AccountName,
          Parent = InitiatingProcessFileName,
          ParentCmd = InitiatingProcessCommandLine,
          MountDrive, DllPath, Export,
          ProcessCommandLine, SHA256
| order by Timestamp desc

// Ferocious Kitten / MarkiRAT — Telegram Desktop & Chrome shortcut hijack persistence
let TelegramFolder = @"\AppData\Roaming\Telegram Desktop\";
let ImplantNames = dynamic(["chrome_update.exe","Updater.exe","telegram_update.exe"]);
let TrustedWriters = dynamic(["telegram.exe","updater.exe","msiexec.exe","explorer.exe","googleupdate.exe","chrome.exe","setup.exe"]);
// (1) suspicious binary written into Telegram Desktop user folder
let TelegramDrops =
    DeviceFileEvents
    | where Timestamp > ago(30d)
    | where ActionType in ("FileCreated","FileModified","FileRenamed")
    | where FolderPath has TelegramFolder
    | where FileName endswith ".exe" or FileName endswith ".dll"
    | where tolower(InitiatingProcessFileName) !in (TrustedWriters);
// (2) Chrome / Telegram .lnk re-targeted by a non-installer process
let ShortcutHijacks =
    DeviceFileEvents
    | where Timestamp > ago(30d)
    | where ActionType in ("FileCreated","FileModified")
    | where FileName endswith ".lnk"
    | where tolower(FileName) has_any ("chrome", "telegram")
    | where FolderPath has_any (@"\Desktop\", @"\Start Menu\")
    | where tolower(InitiatingProcessFileName) !in (TrustedWriters);
// (3) processes named like the legit updater but launched from user-writable paths
let MasqueradedProcs =
    DeviceProcessEvents
    | where Timestamp > ago(30d)
    | where FileName in~ (ImplantNames)
    | where FolderPath has_any (@"\AppData\", @"\Users\Public\", @"\ProgramData\")
    | where InitiatingProcessFolderPath !has @"\Program Files\Google\" and InitiatingProcessFolderPath !has @"\Telegram Desktop\";
union isfuzzy=true
    (TelegramDrops    | extend Signal = "telegram_folder_write"),
    (ShortcutHijacks  | extend Signal = "shortcut_target_rewrite"),
    (MasqueradedProcs | extend Signal = "masqueraded_updater_exec"
                      | extend FolderPath = FolderPath
                      | extend InitiatingProcessFileName = InitiatingProcessFileName)
| project Timestamp, Signal, DeviceName,
          AccountName = coalesce(InitiatingProcessAccountName, AccountName),
          FileName, FolderPath, SHA256,
          Writer = InitiatingProcessFileName,
          WriterCmd = InitiatingProcessCommandLine
| order by Timestamp desc

